        file: "typography-step-3.mjs",
        run: "node typography-step-3.mjs | xargs npx prettier --write",
        code: 'const STEPS = [\n[\n  {\n    "cls": "text-h3",\n    "to": "text-h4"\n  },\n  {\n    "cls": "text-h2",\n    "to": "text-h3"\n  },\n  {\n    "cls": "text-h1",\n    "to": "text-h2"\n  },\n  {\n    "cssVar": "--line-height-h3",\n    "to": "--line-height-h4"\n  },\n  {\n    "cssVar": "--line-height-h2",\n    "to": "--line-height-h3"\n  },\n  {\n    "cssVar": "--font-size-h2",\n    "to": "--font-size-h3"\n  },\n  {\n    "cssVar": "--line-height-h1",\n    "to": "--line-height-h2"\n  },\n  {\n    "cssVar": "--font-size-h1",\n    "to": "--font-size-h2"\n  }\n],\n];\n// Renames design-system names in the app (src, autotests, index.html), in text from stdin (--text), in a JSON list of\n// { file, text } (--json), or in the Find and Replace blocks of a changelog\'s Markdown (--markdown).\n// STEPS (set above this code) run in order. Each rule: { color, to } renames <prefix>-<color> classes and\n// --color-<color> variables, where "to" is one name or { fill, stroke, text, default } by how the color is used;\n// { cls, to } renames a class, { cssVar, to } a variable, { literal, to } an exact text. A step\'s rules apply in one pass.\nimport fs from "node:fs";\nimport path from "node:path";\n\nconst SCOPE = ["src", "autotests", "index.html"];\nconst SKIP = ["node_modules", "src/locales", "src/pages/DesignSystem", "src/config/colors.ts"];\nconst EXT = /\\.(tsx|ts|jsx|js|scss|css|html)$/;\nconst PREFIX_KIND = {\n  bg: "fill", from: "fill", via: "fill", to: "fill", fill: "fill", accent: "fill",\n  border: "stroke", "border-t": "stroke", "border-r": "stroke", "border-b": "stroke", "border-l": "stroke",\n  "border-x": "stroke", "border-y": "stroke", "border-s": "stroke", "border-e": "stroke", divide: "stroke",\n  ring: "stroke", "ring-offset": "stroke", outline: "stroke", stroke: "stroke", decoration: "stroke", shadow: "stroke",\n  text: "text", placeholder: "text", caret: "text",\n};\nconst PROPERTY_KIND = [\n  [/^(background|background-color|backgroundColor|background-image|fill|stop-color|stopColor)$/, "fill"],\n  [/^(border|border-[\\w-]+|border[A-Z]\\w*|outline|outline-color|outlineColor|box-shadow|boxShadow|stroke|text-decoration-color|column-rule-color|scrollbar-color)$/, "stroke"],\n  [/^(color|caret-color|caretColor|-webkit-text-fill-color)$/, "text"],\n];\nconst esc = (s) => s.replace(/[.*+?^${}()|[\\]\\\\]/g, "\\\\$&");\nconst alt = (keys) => [...keys].sort((a, b) => b.length - a.length).map(esc).join("|");\nconst pick = (to, kind) => (typeof to === "string" ? to : (to[kind] ?? to.default));\nconst inScope = (file) =>\n  SCOPE.some((d) => file === d || file.startsWith(`${d}/`)) && !SKIP.some((s) => file === s || file.startsWith(`${s}/`));\n\nfunction propertyKind(before) {\n  const match = /([A-Za-z-]+)\\s*:\\s*[^;:{}]*$/.exec(before);\n  const found = match && PROPERTY_KIND.find(([rx]) => rx.test(match[1]));\n  return found ? found[1] : "default";\n}\n\nconst counts = new Map();\nconst unresolved = [];\nconst count = (key) => counts.set(key, (counts.get(key) ?? 0) + 1);\n\nfunction makeRenamer(rules) {\n  const classMap = new Map();\n  const varMap = new Map();\n  const literalMap = new Map();\n  for (const rule of rules) {\n    if (rule.color) {\n      for (const prefix of Object.keys(PREFIX_KIND)) {\n        const name = pick(rule.to, PREFIX_KIND[prefix]);\n        classMap.set(`${prefix}-${rule.color}`, name ? `${prefix}-${name}` : null);\n      }\n      varMap.set(`--color-${rule.color}`, rule.to);\n    } else if (rule.cls) classMap.set(rule.cls, rule.to);\n    else if (rule.cssVar) varMap.set(rule.cssVar, rule.to);\n    else if (rule.literal) literalMap.set(rule.literal, rule.to);\n  }\n  const classRx = classMap.size && new RegExp(`(?<![\\\\w\\\\-\\\\[])(${alt(classMap.keys())})(?![\\\\w\\\\-.])`, "g");\n  const varRx = varMap.size && new RegExp(`(?<![\\\\w-])(${alt(varMap.keys())})(?![\\\\w-])`, "g");\n  const literalRx = literalMap.size && new RegExp(`(${alt(literalMap.keys())})`, "g");\n  const renameLine = (line, where) => {\n    let out = line;\n    if (literalRx) out = out.replace(literalRx, (m) => (count(m), literalMap.get(m)));\n    if (classRx) {\n      out = out.replace(classRx, (m) => {\n        const to = classMap.get(m);\n        if (to == null) return unresolved.push(`${where}: ${m}`), m;\n        return count(m), to;\n      });\n    }\n    if (varRx) {\n      out = out.replace(varRx, (m, _g, offset, whole) => {\n        const to = varMap.get(m);\n        const name = typeof to === "string" ? to : pick(to, propertyKind(whole.slice(0, offset)));\n        if (!name) return unresolved.push(`${where}: ${m}`), m;\n        return count(m), m.startsWith("--color-") ? `--color-${name}` : name;\n      });\n    }\n    return out;\n  };\n  return (text, file) =>\n    text\n      .split("\\n")\n      .map((line, i) => renameLine(line, `${file}:${i + 1}`))\n      .join("\\n");\n}\n\nconst renamers = STEPS.map(makeRenamer);\nconst renameAll = (text, file) => renamers.reduce((out, rename) => rename(out, file), text);\nconst mode = process.argv[2];\nconst stdin = () => fs.readFileSync(0, "utf8");\n\nif (mode === "--text") {\n  process.stdout.write(renameAll(stdin(), "stdin"));\n} else if (mode === "--json") {\n  const items = JSON.parse(stdin());\n  process.stdout.write(JSON.stringify(items.map(({ file, text }) => (inScope(file) ? renameAll(text, file) : text))));\n} else if (mode === "--markdown") {\n  // Edits in the copied Markdown look like "3. src/x.tsx:12 (note)" followed by fenced Find / Replace blocks\n  let file = null;\n  let fence = null;\n  const out = [];\n  for (const line of stdin().split("\\n")) {\n    const heading = /^\\d+\\. (\\S+?)(?::[\\d-]+)?(?: \\(|$)/.exec(line);\n    if (!fence && heading) file = heading[1];\n    if (line.startsWith("```")) {\n      if (fence) {\n        out.push(file && inScope(file) ? renameAll(fence.join("\\n"), file) : fence.join("\\n"), line);\n        fence = null;\n      } else {\n        out.push(line);\n        fence = [];\n      }\n      continue;\n    }\n    if (fence) fence.push(line);\n    else out.push(line);\n  }\n  process.stdout.write(out.join("\\n"));\n} else {\n  const files = [];\n  const walk = (p) => {\n    if (SKIP.some((s) => p === s || p.startsWith(`${s}/`)) || !fs.existsSync(p)) return;\n    if (fs.statSync(p).isDirectory()) fs.readdirSync(p).forEach((f) => walk(path.join(p, f)));\n    else if (EXT.test(p)) files.push(p);\n  };\n  SCOPE.forEach(walk);\n  const changed = [];\n  for (const file of files) {\n    const text = fs.readFileSync(file, "utf8");\n    const next = renameAll(text, file);\n    if (next !== text) {\n      fs.writeFileSync(file, next);\n      changed.push(file);\n    }\n  }\n  const total = [...counts.values()].reduce((a, b) => a + b, 0);\n  console.error(`Renamed ${total} names in ${changed.length} files.`);\n  if (unresolved.length) console.error(`Left for the edits (${unresolved.length}):\\n  ${unresolved.join("\\n  ")}`);\n  console.log(changed.join("\\n"));\n}\n',
        expect: "Renamed 24 names in 17 files.",
